<section class="academic-subject-final"><span class="eyebrow">Final grade</span><strong><?php echo esc(grade_display($compactGrade['overall'] ?? null)); ?></strong><p><?php echo !$compactGrade ? 'Pending - Your teacher has not released grades yet.' : esc($compactGrade['status'] . (!empty($compactGrade['scale_label']) ? ' | ' . $compactGrade['scale_label'] : '')); ?></p></section>
<section class="academic-compact-breakdown"><h3><span class="academic-heading-icon" aria-hidden="true">&#9638;</span> Grade Breakdown</h3>
<?php foreach (academic_periods() as $defaultPeriod): $period = $compactGrade['periods'][$defaultPeriod['id']] ?? null; ?>
<div class="academic-period-line"><span><?php echo esc($defaultPeriod['name']); ?> <?php if ($period): ?>(<?php echo esc((string) $period['weight']); ?>%)<?php endif; ?></span><strong><?php echo esc(grade_display($period['overall'] ?? null)); ?></strong><span class="academic-percent-chip"><?php echo isset($period['overall']) ? esc(grade_display($period['overall'])) . '%' : '— %'; ?></span></div>
<?php endforeach; ?>
<div class="academic-period-line academic-total-line"><strong>Final Grade</strong><strong><?php echo esc(grade_display($compactGrade['overall'] ?? null)); ?></strong><span class="academic-percent-chip"><?php echo isset($compactGrade['overall']) ? esc(grade_display($compactGrade['overall'])) . '%' : '— %'; ?></span></div></section>
<?php if ($compactGrade): ?><details class="academic-calculation"><summary>&#9432; How grades are calculated?</summary><p><?php echo isset($compactGrade['periods']) ? 'Category scores use earned points divided by possible points. Category weights determine each period grade; period weights determine the final subject grade.' : 'Category scores use earned points divided by possible points. Overall grades use the configured category weights. This classroom has not configured grading periods.'; ?> <?php echo $compactConfig['missing_policy'] === 'exclude' ? 'Ungraded scores and empty categories are excluded; partial grades use available weights.' : 'Assigned missing scores count as zero.'; ?></p></details><details class="academic-assessment-details"><summary>View assessment details</summary><?php render_grade_breakdown($compactGrade, $compactConfig); ?></details><?php endif; ?>
